import { useState, useEffect } from 'react'

import { PuzzlesBoard } from '../App.js'

import { auth, app, db } from '../firebase.js';
import { doc, collection, setDoc, getDoc, addDoc, updateDoc, arrayUnion, arrayRemove, query, where, orderBy } from 'firebase/firestore';

function AddPuzzleModal(props) {

    const [formPuzzleTitle, setFormPuzzleTitle] = useState('');
    const [formPuzzleURL, setFormPuzzleURL] = useState('');
    const AddPuzzle = async (e) => {
      e.preventDefault();

      const userRef = doc(db, 'users', props.user.uid);

      if(e.target.className === 'addFromRecs') {
        await updateDoc(userRef, {
          puzzles:  arrayUnion(e.target.value)
        })
      }
      else {
        await updateDoc(userRef, {
          puzzles:  arrayUnion("X" + formPuzzleURL + " " + formPuzzleTitle)
        })
        setFormPuzzleTitle('');
        setFormPuzzleURL('');
    }

      props.setChangedPuzzleList(Math.random());
      console.log(props.changedPuzzleList);

    }

    const [recommendations, setRecommendations] = useState([]);
    useEffect(() => {
      const fetchGames = async () => {
      const gamesRef = doc(db, 'games', 'recommendations');
      const gamesSnap = await getDoc(gamesRef);
      setRecommendations(gamesSnap.data().puzzles);
      }
    fetchGames();
    }, []);

    return (
      <>
        <h2>Add Puzzles</h2>
        <form onSubmit={AddPuzzle}>
          <input maxLength='15' type='text' required value={formPuzzleTitle} onChange={(e) => setFormPuzzleTitle(e.target.value)} placeholder='Puzzle Title'/>
          <input type="url" required placeholder="URL (https://puzzle.com)"
          value={formPuzzleURL} onChange={(e) => setFormPuzzleURL(e.target.value)}
          pattern="[Hh][Tt][Tt][Pp][Ss]?:\/\/(?:(?:[a-zA-Z\u00a1-\uffff0-9]+-?)*[a-zA-Z\u00a1-\uffff0-9]+)(?:\.(?:[a-zA-Z\u00a1-\uffff0-9]+-?)*[a-zA-Z\u00a1-\uffff0-9]+)*(?:\.(?:[a-zA-Z\u00a1-\uffff]{2,}))(?::\d{2,5})?(?:\/[^\s]*)?"
          />
          <button type='submit' disabled={!formPuzzleTitle}>Add Your Own</button>
        </form>

        <h3>Recommendations</h3>

        <PuzzlesBoard AddPuzzle={AddPuzzle} showDelete={false} puzzleList={recommendations} toggleModal={props.toggleModal}/>
      </>
    )
  }




export {AddPuzzleModal};
